-- Seed: Secretary workbook "Secretary reports 30 july.xlsx" (RY 2025/26, as of 30 July 2025)
-- Run supabase-treasury.sql first.




-- Link ledger rows to the member roster where the names match.
update public.treasury_entries e
set member_id = m.id
from public.members m
where e.member_id is null
  and e.payer is not null
  and lower(regexp_replace(e.payer, '^(rtn\.?|dr\.?|mr\.?|mrs\.?|er\.?|ms\.?)\s+', '', 'gi'))
      = lower(regexp_replace(m.name, '^(rtn\.?|dr\.?|mr\.?|mrs\.?|er\.?|ms\.?)\s+', '', 'gi'));
